const CAL_START = new Date('2023-01-01T00:00:00Z');
const CAL_END   = new Date('2025-12-31T00:00:00Z');

// Build a fast lookup: 'YYYY-MM-DD' -> row
const NEXUS_BY_DATE = new Map();
for (const r of NEXUS_ROWS) NEXUS_BY_DATE.set(r[0], r);

// Sorted array of just the raw rows (already in date order from the source CSV)
const NEXUS_SORTED = NEXUS_ROWS;

function toISO(d) {
    return d.toISOString().slice(0, 10);
}

function addDays(d, n) {
    const r = new Date(d.getTime());
    r.setUTCDate(r.getUTCDate() + n);
    return r;
}

// Maps a real calendar date to the best available date we have data for:
// - if within [CAL_START, CAL_END], use it directly
// - otherwise, map onto the same month/day in the closest historical year
//   (falls back across 2025 -> 2024 -> 2023 if a Feb-29 etc. doesn't exist)
function mapToCoveredDate(date) {
    if (date >= CAL_START && date <= CAL_END) {
	return { date, isProxy: false };
    }
    const month = date.getUTCMonth();
    const day   = date.getUTCDate();
    for (const year of [2025, 2024, 2023]) {
	const candidate = new Date(Date.UTC(year, month, day));
	if (candidate.getUTCMonth() === month && NEXUS_BY_DATE.has(toISO(candidate))) {
	    return { date: candidate, isProxy: true };
	}
    }
    return { date: CAL_END, isProxy: true };
}

// Returns the raw row array for a given real-world date (mapping to the
// seasonal proxy if the date falls outside the covered calendar).
function rowFor(date) {
    const { date: mapped, isProxy } = mapToCoveredDate(date);
    const row = NEXUS_BY_DATE.get(toISO(mapped));
    return { row, isProxy };
}

// Rows for [start, end) — end exclusive — with proxy-mapping applied per day.
function rowsForWindow(start, end) {
    const out = [];
    let anyProxy = false;
    let d = new Date(start.getTime());
    while (d < end) {
	const { row, isProxy } = rowFor(d);
	if (row) out.push(row);
	if (isProxy) anyProxy = true;
	d = addDays(d, 1);
    }
    return { rows: out, isProxy: anyProxy };
}

// Rows for the N days strictly BEFORE `asOf` (rolling lookback window),
// e.g. lookbackRows(inquiryDate, 30) -> last 30 days before inquiry.
function lookbackRows(asOf, nDays) {
    return rowsForWindow(addDays(asOf, -nDays), asOf);
}

function mean(arr) {
    if (!arr.length) return 0;
    return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function std(arr) {
    if (arr.length < 2) return 0;
    const m = mean(arr);
      return Math.sqrt(mean(arr.map(x => (x - m) ** 2)));
}

function mode(arr) {
    if (!arr.length) return 0;
    const counts = new Map();
    for (const v of arr) counts.set(v, (counts.get(v) || 0) + 1);
    let best = arr[0], bestN = 0;
    for (const [v, n] of counts) if (n > bestN) { best = v; bestN = n; }
    return best;
}

// EMA with a 7-day decay constant (alpha = 2/(N+1)), seeded with the
// window's simple mean (report 4.3: "EMA ... first-order IIR low-pass filter").
function ema(seriesOldToNew, span) {
    if (!seriesOldToNew.length) return 0;
    const alpha = 2 / (span + 1);
    let e = seriesOldToNew[0];
    for (let i = 1; i < seriesOldToNew.length; i++) {
	e = alpha * seriesOldToNew[i] + (1 - alpha) * e;
    }
    return e;
}

// ── EXACT: reproduces join_transient()'s stay-window average/mode ──────────
const TR_CAT_LABELS = ['Low', 'Medium', 'High', 'Sold Out'];

function transientStayWindowFeatures(arrivalDate, departureDate) {
    const dep = departureDate || addDays(arrivalDate, 1);
    const { rows, isProxy } = rowsForWindow(arrivalDate, dep);
    if (!rows.length) {
	return {
	    tr_transient_occ_of_available: 0,
	    tr_transient_rooms_turned_away: 0,
	    tr_displacement_pressure: 0,
	    transient_displacement_cost: 0,
	    sourceIsProxy: true,
	};
    }
    const occVals   = rows.map(r => r[2]);
    const turnAways = rows.map(r => r[3]);
    const dispCodes = rows.map(r => r[4]);
    const dispCostPerRoom = rows.map(r => r[6]);
    return {
	tr_transient_occ_of_available:  mean(occVals),
	tr_transient_rooms_turned_away: mean(turnAways),
	tr_displacement_pressure:       mode(dispCodes),
	_dispCostPerRoomMean:           mean(dispCostPerRoom),
	sourceIsProxy: isProxy,
    };
}

// ── APPROXIMATED: rolling-window composites as of inquiry_date ─────────────
function rollingFeatures(inquiryDate) {
    const w7   = lookbackRows(inquiryDate, 7);
    const w14  = lookbackRows(inquiryDate, 14);
    const w30  = lookbackRows(inquiryDate, 30);
    const w60  = lookbackRows(inquiryDate, 60);
    const w90  = lookbackRows(inquiryDate, 90);

    const occ7  = mean(w7.rows.map(r => r[1]));
    const occ30 = mean(w30.rows.map(r => r[1]));
    const occ90 = mean(w90.rows.map(r => r[1]));

    const velocity_7_30  = occ7 - occ30;
    const velocity_30_90 = occ30 - occ90;
    let occupancy_acceleration = velocity_7_30 - velocity_30_90;
    // Winsorise to the pipeline's own reported p1/p99 clip bounds (report 4.4)
    occupancy_acceleration = Math.max(-14.147, Math.min(9.575, occupancy_acceleration));

    const revenue60 = w60.rows.map(r => r[7]);
    const revenue_volatility_60d = std(revenue60);

    const disp7 = w7.rows.map(r => r[5]); // oldest -> newest (rowsForWindow walks forward)
    const displacement_ema_7d = ema(disp7, 7);

    const isProxy = w7.isProxy || w30.isProxy || w90.isProxy || w60.isProxy;

    return {
	occupancy_velocity_7_30d: velocity_7_30,
	occupancy_acceleration,
	revenue_volatility_60d,
	displacement_ema_7d,
	sourceIsProxy: isProxy,
    };
}

// night_variance_pct — coefficient of variation of Total_Occupancy_Pct across
// the RFP's own stay-window nights (inferred interpretation, see header note).
function nightVariancePct(arrivalDate, departureDate) {
    const dep = departureDate || addDays(arrivalDate, 1);
    const { rows } = rowsForWindow(arrivalDate, dep);
    if (rows.length < 2) return 0;
    const occ = rows.map(r => r[1]);
    const m = mean(occ);
    if (!m) return 0;
    return std(occ) / m;
}

// Main entry point used by modelFeatures.js. `arrivalDate`/`departureDate`
// are JS Date objects (UTC midnight); `inquiryDate` likewise.
export function buildTransientFeatures({ arrivalDate, departureDate, inquiryDate, roomBlock }) {
    const stay = transientStayWindowFeatures(arrivalDate, departureDate);
    const roll = rollingFeatures(inquiryDate || arrivalDate);
    const nv   = nightVariancePct(arrivalDate, departureDate);

    return {
	tr_transient_occ_of_available:  stay.tr_transient_occ_of_available,
	tr_transient_rooms_turned_away: stay.tr_transient_rooms_turned_away,
	tr_displacement_pressure:       stay.tr_displacement_pressure,
	transient_displacement_cost:    (stay._dispCostPerRoomMean || 0) * (roomBlock || 0),
	occupancy_velocity_7_30d:       roll.occupancy_velocity_7_30d,
	occupancy_acceleration:         roll.occupancy_acceleration,
	revenue_volatility_60d:         roll.revenue_volatility_60d,
	displacement_ema_7d:            roll.displacement_ema_7d,
	night_variance_pct:             nv,
	// Genuinely unknown composites — see header note. Left at neutral 0
	// rather than fabricated.
	capacity_risk_score:               0,
	revenue_intensity:                 0,
	tactical_compression_opportunity:  0,
	lead_time_deviation:               0,
	sourceIsProxy: stay.sourceIsProxy || roll.sourceIsProxy,
    };
}

export const TRANSIENT_CALENDAR_RANGE = { start: '2023-01-01', end: '2025-12-31' };

// ─── Capacity-based displacement ─────────────────────────────────────────────
// Replaces the old linear rule used on the Strategies screen:
//     baseline_adr × room_block × nights × 0.28 × forecasted_occupancy
// which charged displacement even when the hotel had empty rooms and
// understated it on sold-out nights.
//
// For each night d of the stay:
//   transient demand D_d  = transient rooms sold + transient rooms turned away
//                           (from the transient calendar; unconstrained demand)
//   capacity C_d          = total rooms − group rooms already committed
//                           (from booked_events via bookedMap — NOT the
//                           calendar's historical group column, which belongs
//                           to past years' groups when the date is a proxy)
//   displaced rooms       = clamp(block + D_d − C_d, 0, min(block, D_d))
//   displacement cost     = Σ_d displaced rooms × transient ADR_d
//
// The full contracted block is used (not expected pickup): blocked rooms are
// held out of transient inventory until cutoff whether or not they are used.
//
// Calendar data ends 2025-12-31; later dates use the seasonal proxy
// (same month/day in an earlier year). `isProxy` flags this so the UI can
// disclose that displacement is based on estimated demand.
export function computeDisplacement({ arrivalDate, departureDate, roomBlock, bookedMap = {}, totalRooms = 220 }) {
    const block = Math.max(0, Number(roomBlock) || 0);
    const dep = departureDate && departureDate > arrivalDate ? departureDate : addDays(arrivalDate, 1);
    const perNight = [];
    let total = 0, displacedRoomNights = 0, anyProxy = false, anyModeled = false;

    for (let d = new Date(arrivalDate.getTime()); d < dep; d = addDays(d, 1)) {
	const iso = toISO(d);
	const committed = Number(bookedMap[iso]?.rooms) || 0;
	const capacity  = Math.max(0, totalRooms - committed);
	const fc = TRANSIENT_FORECAST[iso];
	let demand, adr, displaced, isProxy = false, modeled = false;
	if (fc) {
	    // Modeled demand (src/transientForecast.js): displacement is convex in demand,
	    // so take its expectation over p10 / p50 / p90 (weights .3 / .4 / .3)
	    // instead of evaluating it at the median only.
	    modeled = true; anyModeled = true;
	    const disp = (D) => Math.max(0, Math.min(block + D - capacity, block, D));
	    demand = fc[0]; adr = fc[1];
	    displaced = 0.3 * disp(fc[2]) + 0.4 * disp(fc[0]) + 0.3 * disp(fc[3]);
	} else {
	    const r = rowFor(d);
	    isProxy = r.isProxy;
	    if (isProxy) anyProxy = true;
	    if (!r.row) continue;
	    // Row columns: [date, totalOccPct, transientOccOfAvailable, turnedAway,
	    //               pressureCode, totalDispCost, dispCostPerRoom,
	    //               transientRevenue, transientADR, groupRoomsOnBooks]
	    const row = r.row;
	    const calGroup      = Number(row[9]) || 0;
	    const transientSold = Math.round((Number(row[2]) || 0) / 100 * Math.max(0, totalRooms - calGroup));
	    demand = transientSold + (Number(row[3]) || 0);
	    adr    = Number(row[8]) || 0;
	    displaced = Math.max(0, Math.min(block + demand - capacity, block, demand));
	}
	const cost = displaced * adr;

	total += cost;
	displacedRoomNights += displaced;
	perNight.push({ date: iso, transientDemand: demand, committed, capacity,
			displacedRooms: Math.round(displaced * 10) / 10, transientADR: adr, cost: Math.round(cost), isProxy, modeled });
    }

    return {
	total: Math.round(total),
	displacedRoomNights: Math.round(displacedRoomNights * 10) / 10,
	perNight,
	isProxy: anyProxy,
	isModeled: anyModeled,
    };
}
